SELECT COUNT(DISTINCT q.id)
FROM quote q
WHERE q.deleted = 0
AND q.status = 1

    AND q.category_id = #{categoryId}


    AND q.created_id = #{userId}


    AND q.original = #{original}


    AND q.content LIKE CONCAT('%', #{quoteKeyword}, '%')


    AND q.id IN (
    SELECT quote_id
    FROM quote_tag
    WHERE tag_id IN

        #{tagId}

    GROUP BY quote_id
    HAVING COUNT(DISTINCT tag_id) = #{tagIdsSize}
    )

SELECT q.*
FROM quote q
WHERE q.deleted = 0
AND q.status = 1


    AND q.category_id = #{categoryId}


    AND q.created_id = #{userId}


    AND q.original = #{original}


    AND q.content LIKE CONCAT('%', #{quoteKeyword}, '%')



    AND q.id IN (
    SELECT quote_id
    FROM quote_tag
    WHERE tag_id IN

        #{tagId}

    GROUP BY quote_id
    HAVING COUNT(DISTINCT tag_id) = #{tagIdsSize}
    )

ORDER BY q.created_time DESC
LIMIT #{pageNum}, #{pageSize}

SELECT q.original
FROM quote q
WHERE q.id = #{quoteId}

SELECT * FROM quote WHERE deleted = 0 AND status = 1
AND content LIKE CONCAT('%', #{keyword}, '%')
ORDER BY RAND() LIMIT #{quoteCount}
